create or replace function public.product_charge_rules_list_v610(p_tenant_id uuid,p_product_variant_id uuid,p_location_id uuid,p_device_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_rows jsonb; begin perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','view'); if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if; select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'product_variant_id',r.product_variant_id,'charge_catalog_id',r.charge_catalog_id,'order_type',r.order_type,'quantity_mode',r.quantity_mode,'quantity_value',r.quantity_value,'active',r.active,'charge_code',c.code,'charge_name',c.name,'charge_kind',c.charge_kind,'service_variant_id',c.service_variant_id) order by c.name,r.order_type),'[]'::jsonb) into v_rows from public.product_charge_rules_v610 r join public.sales_charge_catalog_v610 c on c.id=r.charge_catalog_id and c.tenant_id=r.tenant_id where r.tenant_id=p_tenant_id and r.product_variant_id=p_product_variant_id; return jsonb_build_object('rules',v_rows); end; $$;;
